From 99b34630d07c2eca29fdf1a5e695829d924a73a9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:51:33 +0100
Subject: [PATCH] daemon: Keep and redetect DDC/CI displays that stop answering

A monitor that stopped answering DDC/CI for a moment, like one set to
another input or just woken up, lost brightness control until powerdevil
restarted. Now writes keep retrying and lost displays get redetected.

BUG: 528077
---
 daemon/controllers/ddcutildetector.cpp | 66 ++++++++++++++++++++++++--
 daemon/controllers/ddcutildisplay.cpp  | 29 ++++++++---
 daemon/controllers/ddcutildisplay.h    |  5 +-
 3 files changed, 87 insertions(+), 13 deletions(-)

diff --git a/daemon/controllers/ddcutildetector.cpp b/daemon/controllers/ddcutildetector.cpp
index 1a65115ec..43d160eee 100644
--- a/daemon/controllers/ddcutildetector.cpp
+++ b/daemon/controllers/ddcutildetector.cpp
@@ -11,11 +11,16 @@
 #include <powerdevil_debug.h>

 #include <QMutex>
+#include <QSet>
+#include <QTimer>

+#include <chrono>
 #include <map>
 #include <memory> // std::unique_ptr
 #include <span>

+using namespace std::chrono_literals;
+
 #ifdef WITH_DDCUTIL
 #include <ddcutil_c_api.h>

@@ -23,6 +28,9 @@

 #if DDCUTIL_VERSION >= QT_VERSION_CHECK(2, 1, 0)
 void ddcaCallback(DDCA_Display_Status_Event event);
+
+// a monitor can take a few seconds after waking up or being switched back on until it answers DDC/CI
+constexpr std::array<std::chrono::milliseconds, 5> s_redetectRetryIntervals = {2s, 5s, 10s, 30s, 60s};
 #endif

 class DDCutilPrivateSingleton : public QObject
@@ -52,11 +60,12 @@ Q_SIGNALS:
     void displaysChanged();

     // emitted from the ddcutil callback from potentially outside the object's thread
-    void displayAdded();
+    void displayAdded(const QString &id);
     void displayRemoved(const QString &id);

 private Q_SLOTS:
     void redetect();
+    void redetectDisplay(const QString &id);
     void removeDisplay(const QString &id);

 private:
@@ -64,6 +73,11 @@ private:
     std::map<QString, std::unique_ptr<DDCutilDisplay>> m_pendingDisplays;
     // ddcutil has global state, let's avoid simultaneous access to its open display map
     QMutex m_openDisplayMutex;
+    QSet<QString> m_knownDisplayIds;
+    // known displays that should be there, but didn't answer when displays were last detected
+    QSet<QString> m_missingDisplayIds;
+    QTimer m_redetectTimer;
+    uint m_redetectRetryCounter = 0;
     bool m_performedDetection = false;
     bool m_noDdcutil = false;
 };
@@ -107,9 +121,12 @@ DDCutilPrivateSingleton::DDCutilPrivateSingleton()
         return;
     }

-    connect(this, &DDCutilPrivateSingleton::displayAdded, this, &DDCutilPrivateSingleton::redetect);
+    connect(this, &DDCutilPrivateSingleton::displayAdded, this, &DDCutilPrivateSingleton::redetectDisplay);
     connect(this, &DDCutilPrivateSingleton::displayRemoved, this, &DDCutilPrivateSingleton::removeDisplay);

+    m_redetectTimer.setSingleShot(true);
+    connect(&m_redetectTimer, &QTimer::timeout, this, &DDCutilPrivateSingleton::redetect);
+
     ddca_start_watch_displays(DDCA_Display_Event_Class(DDCA_EVENT_CLASS_ALL));
 #endif
 }
@@ -122,7 +139,7 @@ DDCutilPrivateSingleton::~DDCutilPrivateSingleton()
 #if DDCUTIL_VERSION >= QT_VERSION_CHECK(2, 1, 0)
     ddca_stop_watch_displays(false);
     ddca_unregister_display_status_callback(ddcaCallback);
-    disconnect(this, &DDCutilPrivateSingleton::displayAdded, this, &DDCutilPrivateSingleton::redetect);
+    disconnect(this, &DDCutilPrivateSingleton::displayAdded, this, &DDCutilPrivateSingleton::redetectDisplay);
     disconnect(this, &DDCutilPrivateSingleton::displayRemoved, this, &DDCutilPrivateSingleton::removeDisplay);
 #endif
 }
@@ -166,6 +183,15 @@ void DDCutilPrivateSingleton::detect()
                 removeDisplay(id);
             }
         });
+        // queued, as redetecting deletes the display
+        connect(
+            display.get(),
+            &DDCutilDisplay::connectionLost,
+            this,
+            [this, id]() {
+                redetectDisplay(id);
+            },
+            Qt::QueuedConnection);

         if (!display->supportsBrightness()) {
             qCWarning(POWERDEVIL) << "[DDCutilDetector]: Display" << display->label()
@@ -174,6 +200,7 @@ void DDCutilPrivateSingleton::detect()
             connect(display.get(), &DDCutilDisplay::retryInitFinished, this, [this, id](bool success) {
                 auto displayNode = m_pendingDisplays.extract(id);
                 if (success) {
+                    m_knownDisplayIds.insert(id);
                     m_displays.insert(std::move(displayNode));
                     Q_EMIT displaysChanged();
                 }
@@ -184,6 +211,7 @@ void DDCutilPrivateSingleton::detect()
         qCDebug(POWERDEVIL) << "[DDCutilDetector]: Display supports Brightness, adding handle to list";

         m_pendingDisplays.erase(id);
+        m_knownDisplayIds.insert(id);
         m_displays.emplace(id, std::move(display));
     }
 }
@@ -214,15 +242,42 @@ void DDCutilPrivateSingleton::redetect()
     if (!m_displays.empty() || !invalidDisplays.empty()) {
         Q_EMIT displaysChanged();
     }
+
+    m_missingDisplayIds.removeIf([this](const QString &id) {
+        return m_displays.contains(id);
+    });
+    if (m_missingDisplayIds.isEmpty()) {
+        m_redetectTimer.stop();
+        m_redetectRetryCounter = 0;
+    } else if (!m_redetectTimer.isActive()) {
+        if (m_redetectRetryCounter < s_redetectRetryIntervals.size()) {
+            m_redetectTimer.start(s_redetectRetryIntervals[m_redetectRetryCounter]);
+            ++m_redetectRetryCounter;
+            qCDebug(POWERDEVIL) << "[DDCutilDetector]: Displays" << m_missingDisplayIds << "did not answer, redetecting in" << m_redetectTimer.interval()
+                                << "ms";
+        } else {
+            qCWarning(POWERDEVIL) << "[DDCutilDetector]: Displays" << m_missingDisplayIds << "did not answer after redetecting";
+            m_missingDisplayIds.clear();
+            m_redetectRetryCounter = 0;
+        }
+    }
 #endif
 }

+void DDCutilPrivateSingleton::redetectDisplay(const QString &id)
+{
+    if (m_knownDisplayIds.contains(id)) {
+        m_missingDisplayIds.insert(id);
+    }
+    redetect();
+}
+
 #if DDCUTIL_VERSION >= QT_VERSION_CHECK(2, 1, 0)
 void DDCutilPrivateSingleton::displayStatusChanged(DDCA_Display_Status_Event &event)
 {
     if (event.event_type == DDCA_EVENT_DISPLAY_CONNECTED) {
         qCDebug(POWERDEVIL) << "[DDCutilDetector]: DDCA_EVENT_DISPLAY_CONNECTED signal arrived";
-        Q_EMIT displayAdded();
+        Q_EMIT displayAdded(DDCutilDisplay::generatePathId(event.io_path));
     } else if (event.event_type == DDCA_EVENT_DISPLAY_DISCONNECTED) {
         qCDebug(POWERDEVIL) << "[DDCutilDetector]: DDCA_EVENT_DISPLAY_DISCONNECTED signal arrived";
         Q_EMIT displayRemoved(DDCutilDisplay::generatePathId(event.io_path));
@@ -231,7 +286,7 @@ void DDCutilPrivateSingleton::displayStatusChanged(DDCA_Display_Status_Event &ev
         Q_EMIT displayRemoved(DDCutilDisplay::generatePathId(event.io_path));
     } else if (event.event_type == DDCA_EVENT_DPMS_AWAKE) {
         qCDebug(POWERDEVIL) << "[DDCutilDetector]: DDCA_EVENT_DPMS_AWAKE signal arrived";
-        Q_EMIT displayAdded();
+        Q_EMIT displayAdded(DDCutilDisplay::generatePathId(event.io_path));
     }
 }
 #endif
@@ -239,6 +294,7 @@ void DDCutilPrivateSingleton::displayStatusChanged(DDCA_Display_Status_Event &ev
 void DDCutilPrivateSingleton::removeDisplay(const QString &id)
 {
     m_pendingDisplays.erase(id); // cancel any scheduled initialization retries
+    m_missingDisplayIds.remove(id);

     if (auto deletedAfterEmit = m_displays.extract(id); !deletedAfterEmit.empty()) {
         qCDebug(POWERDEVIL) << "[DDCutilDetector]: Removing display" << id;
diff --git a/daemon/controllers/ddcutildisplay.cpp b/daemon/controllers/ddcutildisplay.cpp
index 1e0a2f209..00d42c3f2 100644
--- a/daemon/controllers/ddcutildisplay.cpp
+++ b/daemon/controllers/ddcutildisplay.cpp
@@ -20,6 +20,9 @@ constexpr std::chrono::milliseconds s_initialWriteDelay = 50ms;
 // vdu_controls recommend half second delay
 constexpr std::chrono::milliseconds s_debounceInterval = 500ms;
 constexpr std::array<std::chrono::milliseconds, 3> s_backoffRetryIntervals = {1s, 2s, 3s};
+// keep trying a while longer, e.g. for a monitor that shows another input or is still waking up
+constexpr std::chrono::milliseconds s_slowRetryInterval = 30s;
+constexpr uint s_slowRetryCount = 10;

 #ifdef WITH_DDCUTIL
 constexpr DDCA_Vcp_Feature_Code BRIGHTNESS_VCP_FEATURE_CODE = 0x10;
@@ -213,11 +216,18 @@ void DDCutilDisplay::onSetBrightnessTimeout()
     Q_EMIT ddcBrightnessChangeRequested(m_pendingBrightness.value(), this);
 }

-void DDCutilDisplay::ddcBrightnessChangeFinished(bool success)
+void DDCutilDisplay::ddcBrightnessChangeFinished(bool success, bool displayLost)
 {
     if (!success) {
-        if (m_retryCounter < s_backoffRetryIntervals.size()) {
-            m_timer->start(s_backoffRetryIntervals[m_retryCounter]);
+        if (displayLost) {
+            qCWarning(POWERDEVIL) << "[DDCutilDisplay]:" << m_label << "lost its DDC/CI connection";
+            m_pendingBrightness.reset();
+            m_retryCounter = 0;
+            Q_EMIT connectionLost();
+            return;
+        }
+        if (m_retryCounter < s_backoffRetryIntervals.size() + s_slowRetryCount) {
+            m_timer->start(m_retryCounter < s_backoffRetryIntervals.size() ? s_backoffRetryIntervals[m_retryCounter] : s_slowRetryInterval);
             ++m_retryCounter;
             qCWarning(POWERDEVIL) << "[DDCutilDisplay]:" << m_label << "retrying to set DDC/CI brightness in" << m_timer->interval()
                                   << "milliseconds - attempt no." << m_retryCounter;
@@ -225,8 +235,6 @@ void DDCutilDisplay::ddcBrightnessChangeFinished(bool success)
         }
         qCWarning(POWERDEVIL) << "[DDCutilDisplay]:" << m_label << "failed to set DDC/CI brightness";
         m_pendingBrightness.reset();
-        m_supportsBrightness = false;
-        Q_EMIT supportsBrightnessChanged(false);
         return;
     }

@@ -244,17 +252,25 @@ void BrightnessWorker::ddcSetBrightness(int value, DDCutilDisplay *display)

     DDCA_Display_Handle displayHandle = nullptr;
     DDCA_Status status = DDCRC_OK;
+    bool displayLost = false;
+    // libddcutil won't use a display reference again after it saw the display disconnected,
+    // even if the display is back: only redetecting displays gives a working one
+    auto checkDisplayLost = [&displayLost](DDCA_Status result) {
+        displayLost = displayLost || result == DDCRC_DISCONNECTED || result == DDCRC_INVALID_DISPLAY || result == DDCRC_ARG;
+    };

     {
         QMutexLocker locker(display->m_openDisplayMutex);

         if (status = ddca_open_display2(display->m_displayRef, true, &displayHandle); status != DDCRC_OK) {
             qCWarning(POWERDEVIL) << "[DDCutilDisplay]: ddca_open_display2" << status;
+            checkDisplayLost(status);
         } else {
             int currentBrightness = -1;
             DDCA_Non_Table_Vcp_Value vcpValue;
             if (status = ddca_get_non_table_vcp_value(displayHandle, BRIGHTNESS_VCP_FEATURE_CODE, &vcpValue); status != DDCRC_OK) {
                 qCWarning(POWERDEVIL) << "[DDCutilDisplay]: ddca_get_non_table_vcp_value" << status;
+                checkDisplayLost(status);
             } else {
                 currentBrightness = vcpValue.sh << 8 | vcpValue.sl;
             }
@@ -267,6 +283,7 @@ void BrightnessWorker::ddcSetBrightness(int value, DDCutilDisplay *display)

                 if (status = ddca_set_non_table_vcp_value(displayHandle, BRIGHTNESS_VCP_FEATURE_CODE, sh, sl); status != DDCRC_OK) {
                     qCWarning(POWERDEVIL) << "[DDCutilDisplay]: ddca_set_non_table_vcp_value" << status;
+                    checkDisplayLost(status);
                 }
             }

@@ -277,7 +294,7 @@ void BrightnessWorker::ddcSetBrightness(int value, DDCutilDisplay *display)
         }
     }

-    Q_EMIT ddcBrightnessChangeApplied(status == DDCRC_OK);
+    Q_EMIT ddcBrightnessChangeApplied(status == DDCRC_OK, displayLost);
 #endif
 }

diff --git a/daemon/controllers/ddcutildisplay.h b/daemon/controllers/ddcutildisplay.h
index c23b68442..c1f69bfa8 100644
--- a/daemon/controllers/ddcutildisplay.h
+++ b/daemon/controllers/ddcutildisplay.h
@@ -55,11 +55,12 @@ public:
 Q_SIGNALS:
     void retryInitFinished(bool success);
     void supportsBrightnessChanged(bool supportsBrightness);
+    void connectionLost();
     void ddcBrightnessChangeRequested(int value, DDCutilDisplay *display);

 private Q_SLOTS:
     void onSetBrightnessTimeout();
-    void ddcBrightnessChangeFinished(bool success);
+    void ddcBrightnessChangeFinished(bool success, bool displayLost);

 private:
 #ifdef WITH_DDCUTIL
@@ -88,5 +89,5 @@ class BrightnessWorker : public QObject
 private Q_SLOTS:
     void ddcSetBrightness(int value, DDCutilDisplay *display);
 Q_SIGNALS:
-    void ddcBrightnessChangeApplied(bool isSuccessful);
+    void ddcBrightnessChangeApplied(bool isSuccessful, bool isDisplayLost);
 };
